#[derive(Clone,Copy,Default)]
struct Cell { sand: bool, moved: bool }
fn tick(column:&mut [Cell]) {
    for cell in column.iter_mut() { cell.moved=false; }
    for row in (0..column.len().saturating_sub(1)).rev() {
        if column[row].sand && !column[row].moved && !column[row+1].sand {
            column.swap(row,row+1);
            column[row+1].moved=true;
        }
    }
}
fn main() {
    let mut column=[Cell::default();6];
    column[0].sand=true;
    tick(&mut column);
    assert!(column[1].sand);
    assert_eq!(column.iter().filter(|c|c.sand).count(),1);
    println!("one tick, one row");
}

fn choose_side(left:Option<usize>,right:Option<usize>,tick:u64)->Option<usize> {
    let (first,second)=if tick%2==0 {(left,right)} else {(right,left)};
    first.or(second)
}
fn main() {
    assert_eq!(choose_side(Some(3),Some(5),0),Some(3));
    assert_eq!(choose_side(Some(3),Some(5),1),Some(5));
    assert_eq!(choose_side(None,Some(5),0),Some(5));
    assert_eq!(choose_side(None,None,1),None);
    println!("deterministic tie-break verified");
}

fn pick(mouse_x:f32,mouse_y:f32,view_w:f32,view_h:f32)->Option<(i32,i32)> {
    if !mouse_x.is_finite() || !mouse_y.is_finite() || mouse_x<0.0
        || mouse_y<0.0 || mouse_x>=view_w || mouse_y>=view_h {return None;}
    Some(((mouse_x/4.0).floor() as i32,(mouse_y/4.0).floor() as i32))
}
fn main() {
    assert_eq!(pick(48.5,20.1,1280.0,720.0),Some((12,5)));
    assert_eq!(pick(-0.1,20.0,1280.0,720.0),None);
    assert_eq!(pick(1280.0,20.0,1280.0,720.0),None);
    println!("view picking checks passed");
}

